def google_search(api_key, q, locale=None, country=None, safe_search=None, allow_empty_query=None, result_format=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0337000" if __import__("os").path.isdir("./environment_mix/0337000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.isoformat()

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if isinstance(v, str):
            s = v
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(s)
                return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
            except Exception:
                return None
        return None

    def _minute_window_start(dt):
        return dt.replace(second=0, microsecond=0)

    def _day_window_start(dt):
        return dt.replace(hour=0, minute=0, second=0, microsecond=0)

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _redact(obj, raw_api_key):
        # Best-effort redaction of obvious secrets and the client api key.
        secret_keys = {
            "authorization", "proxy-authorization", "x-api-key", "api_key", "apikey", "key", "token",
            "access_token", "refresh_token", "secret", "password", "client_secret"
        }

        def _walk(x):
            if isinstance(x, dict):
                out = {}
                for k, v in x.items():
                    lk = str(k).lower()
                    if lk in secret_keys:
                        out[k] = "[REDACTED]"
                    else:
                        out[k] = _walk(v)
                return out
            if isinstance(x, list):
                return [_walk(i) for i in x]
            if isinstance(x, str):
                if raw_api_key and raw_api_key in x:
                    return x.replace(raw_api_key, "[REDACTED]")
                return x
            return x

        return _walk(obj)

    # ---- Validate inputs (types/enums) ----
    if api_key is None or not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key is required and must be a non-empty string", field="api_key")
    if q is None or not isinstance(q, str):
        return _err("VALIDATION_ERROR", "q is required and must be a string", field="q")

    if locale is not None and not isinstance(locale, str):
        return _err("VALIDATION_ERROR", "locale must be a string", field="locale")
    if country is not None and not isinstance(country, str):
        return _err("VALIDATION_ERROR", "country must be a string", field="country")
    if safe_search is not None:
        if not isinstance(safe_search, str):
            return _err("VALIDATION_ERROR", "safe_search must be a string", field="safe_search")
        if safe_search not in ("off", "moderate", "strict"):
            return _err("VALIDATION_ERROR", "safe_search must be one of: off, moderate, strict", field="safe_search")
    if allow_empty_query is not None and not isinstance(allow_empty_query, bool):
        return _err("VALIDATION_ERROR", "allow_empty_query must be a boolean", field="allow_empty_query")
    if result_format is not None:
        if not isinstance(result_format, str):
            return _err("VALIDATION_ERROR", "result_format must be a string", field="result_format")
        if result_format not in ("json",):
            return _err("VALIDATION_ERROR", "result_format must be 'json'", field="result_format")
    if result_format is None:
        result_format = "json"

    started_wall = time.time()
    now = _now()

    # ---- Resolve API key context (match by id OR by client-visible prefix value) ----
    api_keys = _load("api_keys.json")
    # Never compare to key_hash; accept either id match or prefix match (client-visible).
    key_row = None
    for r in api_keys:
        if not isinstance(r, dict):
            continue
        if r.get("id") == api_key or r.get("key_prefix") == api_key:
            key_row = r
            break
    if key_row is None:
        # No authenticated context exists; still must record dynamics? No key_id to attach.
        # Spec: create search_requests row per invocation tied to authenticated API key.
        # Without auth we cannot create a valid row (FK), so return UNAUTHORIZED.
        return _err("UNAUTHORIZED", "Invalid API key")

    api_key_id = key_row.get("id")

    # ---- Prepare rate-limit counter windows ----
    counters = _load("rate_limit_counters.json")

    minute_start = _minute_window_start(now)
    day_start = _day_window_start(now)
    minute_start_s = _iso(minute_start)
    day_start_s = _iso(day_start)

    def _get_or_create_counter(window_type, window_start_s):
        nonlocal counters
        for c in counters:
            if not isinstance(c, dict):
                continue
            if c.get("api_key_id") == api_key_id and c.get("window_type") == window_type and c.get("window_start") == window_start_s:
                return c
        c = {
            "id": _gen_id("rlc"),
            "api_key_id": api_key_id,
            "window_type": window_type,
            "window_start": window_start_s,
            "request_count": 0,
            "success_count": 0,
            "rejected_count": 0,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        counters.append(c)
        return c

    minute_counter = _get_or_create_counter("minute", minute_start_s)
    day_counter = _get_or_create_counter("day", day_start_s)

    # ---- Create request row (queued -> running/succeeded/failed/rejected) ----
    search_requests = _load("search_requests.json")
    search_results = _load("search_results.json")

    req_id = _gen_id("srq")
    req_row = {
        "id": req_id,
        "api_key_id": api_key_id,
        "status": "queued",
        "tool_name": "google_search",
        "input_params": {
            "api_key": api_key,
            "q": q,
            "locale": locale,
            "country": country,
            "safe_search": safe_search,
            "allow_empty_query": allow_empty_query,
            "result_format": result_format,
        },
        "query_text": q,
        "locale": locale,
        "country": country,
        "safe_search": safe_search,
        "upstream_provider": "serper",
        "upstream_request_id": None,
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "duration_ms": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    search_requests.append(req_row)

    # Count this authenticated request for rate limit window (includes failed/rejected).
    minute_counter["request_count"] = int(minute_counter.get("request_count") or 0) + 1
    minute_counter["updated_at"] = _iso(now)
    day_counter["request_count"] = int(day_counter.get("request_count") or 0) + 1
    day_counter["updated_at"] = _iso(now)

    # Persist early so audit trail exists even if later logic fails.
    _save("search_requests.json", search_requests)
    _save("rate_limit_counters.json", counters)

    def _update_req_terminal(status, http_status, error_code=None, error_message=None, create_result_payload=None, success=False):
        nonlocal search_requests, search_results, counters, minute_counter, day_counter, key_row, api_keys
        end = _now()
        # Transition enforcement:
        if req_row["status"] in ("succeeded", "failed", "rejected"):
            return False, _err("INVALID_TRANSITION", f"Request already in terminal state '{req_row['status']}'")
        if req_row["status"] == "queued":
            # Move to rejected directly or to running first depending on status
            if status == "rejected":
                req_row["status"] = "rejected"
            else:
                req_row["status"] = "running"
        if req_row["status"] == "running":
            if status not in ("succeeded", "failed"):
                if status == "rejected":
                    # queued->rejected is allowed; running->rejected is not per transitions
                    return False, _err("INVALID_TRANSITION", "running requests cannot transition to rejected")
                return False, _err("INVALID_TRANSITION", f"Invalid transition to {status}")
            req_row["status"] = status

        req_row["http_status"] = http_status
        req_row["error_code"] = error_code
        req_row["error_message"] = error_message
        if req_row.get("started_at") is None:
            req_row["started_at"] = _iso(_parse_dt(req_row.get("created_at")) or now)
        req_row["finished_at"] = _iso(end)
        dur = int(round((time.time() - started_wall) * 1000))
        if dur < 0:
            dur = 0
        req_row["duration_ms"] = dur
        req_row["updated_at"] = _iso(end)

        # Update key last_used_at
        key_row["last_used_at"] = _iso(end)
        key_row["updated_at"] = _iso(end)

        # Update counters for terminal state
        if status == "rejected":
            minute_counter["rejected_count"] = int(minute_counter.get("rejected_count") or 0) + 1
            minute_counter["updated_at"] = _iso(end)
            day_counter["rejected_count"] = int(day_counter.get("rejected_count") or 0) + 1
            day_counter["updated_at"] = _iso(end)
        if success:
            # Only succeeded upstream calls increment success_count (daily quota uses this).
            minute_counter["success_count"] = int(minute_counter.get("success_count") or 0) + 1
            minute_counter["updated_at"] = _iso(end)
            day_counter["success_count"] = int(day_counter.get("success_count") or 0) + 1
            day_counter["updated_at"] = _iso(end)

        # Create result row if succeeded
        result_row = None
        if status == "succeeded":
            # ensure unique(request_id)
            for r in search_results:
                if isinstance(r, dict) and r.get("request_id") == req_id:
                    result_row = r
                    break
            if result_row is None:
                redacted_payload = _redact(create_result_payload if create_result_payload is not None else {}, api_key)
                result_row = {
                    "id": _gen_id("srr"),
                    "request_id": req_id,
                    "result_format": "json",
                    "raw_payload": redacted_payload,
                    "top_result_count": None,
                    "has_answer_box": None,
                    "created_at": _iso(end),
                    "updated_at": _iso(end),
                }
                # Optional derived fields
                try:
                    organic = redacted_payload.get("organic")
                    if isinstance(organic, list):
                        result_row["top_result_count"] = len(organic)
                except Exception:
                    pass
                try:
                    ab = redacted_payload.get("answerBox")
                    if isinstance(ab, dict):
                        result_row["has_answer_box"] = True
                    elif ab is None:
                        result_row["has_answer_box"] = False
                except Exception:
                    pass
                search_results.append(result_row)
        else:
            # Ensure no result row created for failed/rejected
            # (Do not delete if pre-existing due to prior bug; but enforce "must not be created" for this call.)
            pass

        # Persist
        _save("search_requests.json", search_requests)
        _save("search_results.json", search_results)
        _save("rate_limit_counters.json", counters)
        _save("api_keys.json", api_keys)

        return True, (req_row, result_row)

    # ---- Reject if key not active ----
    kstatus = key_row.get("status")
    if kstatus != "active":
        http_status = 401 if kstatus in (None, "revoked") else 403
        ok, out = _update_req_terminal(
            status="rejected",
            http_status=http_status,
            error_code="UNAUTHORIZED",
            error_message="API key is not active",
            create_result_payload=None,
            success=False,
        )
        if not ok:
            return out
        req_row_final, _ = out
        return {
            "request": req_row_final,
            "result": None,
        }

    # ---- Empty query enforcement ----
    if q.strip() == "":
        # Allow only if both the call requests it and the key permits it.
        if not (allow_empty_query is True and bool(key_row.get("allow_empty_query")) is True):
            ok, out = _update_req_terminal(
                status="rejected",
                http_status=400,
                error_code="VALIDATION_ERROR",
                error_message="Empty query not allowed for this API key",
                create_result_payload=None,
                success=False,
            )
            if not ok:
                return out
            req_row_final, _ = out
            return {"request": req_row_final, "result": None}

    # ---- Rate limiting check (minute) ----
    rlm = int(key_row.get("rate_limit_per_minute") or 0)
    if rlm > 0 and int(minute_counter.get("request_count") or 0) > rlm:
        ok, out = _update_req_terminal(
            status="rejected",
            http_status=429,
            error_code="RATE_LIMIT",
            error_message="Rate limit exceeded",
            create_result_payload=None,
            success=False,
        )
        if not ok:
            return out
        req_row_final, _ = out
        return {"request": req_row_final, "result": None}

    # ---- Daily quota check (by success_count; only on would-be success) ----
    qpd = int(key_row.get("quota_requests_per_day") or 0)
    # If quota is 0 => unlimited. Otherwise reject when day success_count would exceed quota.
    if qpd > 0:
        would_be_success = int(day_counter.get("success_count") or 0) + 1
        if would_be_success > qpd:
            ok, out = _update_req_terminal(
                status="rejected",
                http_status=429,
                error_code="QUOTA_EXCEEDED",
                error_message="Daily quota exceeded",
                create_result_payload=None,
                success=False,
            )
            if not ok:
                return out
            req_row_final, _ = out
            return {"request": req_row_final, "result": None}

    # ---- Simulated upstream call (offline) ----
    # Transition queued->running
    if req_row["status"] == "queued":
        req_row["status"] = "running"
        req_row["started_at"] = _iso(now)
        req_row["updated_at"] = _iso(now)
        _save("search_requests.json", search_requests)

    # Produce deterministic-ish payload while resembling Serper response shape.
    # No external HTTP performed.
    upstream_payload = {
        "searchParameters": {
            "q": q,
            "gl": country,
            "hl": locale,
            "safe": safe_search,
            "type": "search",
        },
        "organic": [
            {
                "title": f"Result for: {q}" if q.strip() else "Result",
                "link": "https://example.com/",
                "snippet": "Offline simulated Serper response (no network).",
                "position": 1,
            }
        ],
        "credits": 1,
        "provider": "serper",
    }

    # Mark success (200) and create search_results row
    ok, out = _update_req_terminal(
        status="succeeded",
        http_status=200,
        error_code=None,
        error_message=None,
        create_result_payload=upstream_payload,
        success=True,
    )
    if not ok:
        return out
    req_row_final, result_row = out

    return {
        "request": req_row_final,
        "result": result_row,
    }

def whoami(api_key, **_extra):
    import json, os, datetime, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0337000" if __import__("os").path.isdir("./environment_mix/0337000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key is required and must be a non-empty string", field="api_key")

    api_keys = _load("api_keys.json")
    rate_counters = _load("rate_limit_counters.json")

    key_row = None
    # allow id match or sha256(raw) match
    for r in api_keys:
        if isinstance(r, dict) and r.get("id") == api_key:
            key_row = r
            break
    if key_row is None:
        h = hashlib.sha256(api_key.encode("utf-8")).hexdigest()
        for r in api_keys:
            if isinstance(r, dict) and r.get("key_hash") == h:
                key_row = r
                break
    if key_row is None:
        return _err("UNAUTHORIZED", "Invalid API key")

    # update last_used_at and updated_at (observable dynamics)
    key_row["last_used_at"] = now_iso
    key_row["updated_at"] = now_iso
    _save("api_keys.json", api_keys)

    if key_row.get("status") != "active":
        # Tool says FORBIDDEN when not active; map to UNAUTHORIZED? use UNAUTHORIZED code set -> use UNAUTHORIZED per contract
        return _err("UNAUTHORIZED", "API key is not active", status=key_row.get("status"))

    def _truncate_minute(dt):
        return dt.replace(second=0, microsecond=0)

    def _truncate_day(dt):
        return dt.replace(hour=0, minute=0, second=0, microsecond=0)

    minute_iso = _truncate_minute(now).isoformat() + "Z"
    day_iso = _truncate_day(now).isoformat() + "Z"

    def _find(api_key_id, wt, ws):
        for c in rate_counters:
            if isinstance(c, dict) and c.get("api_key_id") == api_key_id and c.get("window_type") == wt and c.get("window_start") == ws:
                return c
        return None

    cmin = _find(key_row["id"], "minute", minute_iso) or {
        "window_start": minute_iso, "request_count": 0, "success_count": 0, "rejected_count": 0
    }
    cday = _find(key_row["id"], "day", day_iso) or {
        "window_start": day_iso, "request_count": 0, "success_count": 0, "rejected_count": 0
    }

    return {
        "api_key": {
            "id": key_row.get("id"),
            "key_prefix": key_row.get("key_prefix"),
            "label": key_row.get("label"),
            "owner_type": key_row.get("owner_type"),
            "owner_id": key_row.get("owner_id"),
            "status": key_row.get("status"),
            "quota_requests_per_day": key_row.get("quota_requests_per_day"),
            "rate_limit_per_minute": key_row.get("rate_limit_per_minute"),
            "allow_empty_query": key_row.get("allow_empty_query"),
            "created_at": key_row.get("created_at"),
            "updated_at": key_row.get("updated_at"),
            "last_used_at": key_row.get("last_used_at"),
        },
        "usage": {
            "minute": {k: cmin.get(k) for k in ("window_start", "request_count", "success_count", "rejected_count")},
            "day": {k: cday.get(k) for k in ("window_start", "request_count", "success_count", "rejected_count")},
        },
        "latency_ms": int((time.time() - t0) * 1000),
    }

def list_api_keys(api_key, owner_type=None, owner_id=None, status=None, key_prefix=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, time, hashlib, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0337000" if __import__("os").path.isdir("./environment_mix/0337000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    # ---- helpers ----
    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v
        if not isinstance(v, str):
            return None
        s = v.strip()
        if s.endswith("Z"):
            s = s[:-1]
        try:
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _dt_key(v):
        dt = _parse_dt(v)
        if dt is None:
            # stable ordering with missing timestamps
            return datetime.datetime(1970, 1, 1)
        return dt

    def _redact_key_row(r):
        # never return raw key material; store doesn't have it anyway
        return {
            "id": r.get("id"),
            "key_prefix": r.get("key_prefix"),
            "label": r.get("label"),
            "owner_type": r.get("owner_type"),
            "owner_id": r.get("owner_id"),
            "status": r.get("status"),
            "quota_requests_per_day": r.get("quota_requests_per_day"),
            "rate_limit_per_minute": r.get("rate_limit_per_minute"),
            "allow_empty_query": r.get("allow_empty_query"),
            "last_used_at": r.get("last_used_at"),
            "created_at": r.get("created_at"),
            "updated_at": r.get("updated_at"),
        }

    def _record_request(api_key_id, status_code, outcome):
        # This service tracks usage in rate_limit_counters; management calls should count toward minute window
        # and should NOT count toward daily search success quota.
        counters = _load("rate_limit_counters.json")
        api_keys_rows = _load("api_keys.json")

        # ensure key exists in store before writing counters
        if not api_key_id:
            return

        minute_start = now.replace(second=0, microsecond=0)
        minute_iso = minute_start.isoformat() + "Z"

        # find or create minute counter
        row = None
        for c in counters:
            if isinstance(c, dict) and c.get("api_key_id") == api_key_id and c.get("window_type") == "minute" and c.get("window_start") == minute_iso:
                row = c
                break
        if row is None:
            row = {
                "id": "serper_rlc_" + secrets.token_hex(12),
                "api_key_id": api_key_id,
                "window_type": "minute",
                "window_start": minute_iso,
                "request_count": 0,
                "success_count": 0,
                "rejected_count": 0,
                "created_at": now_iso,
                "updated_at": now_iso,
            }
            counters.append(row)

        row["request_count"] = int(row.get("request_count") or 0) + 1
        if outcome == "rejected":
            row["rejected_count"] = int(row.get("rejected_count") or 0) + 1
        row["updated_at"] = now_iso

        # also update last_used_at on key if present
        for k in api_keys_rows:
            if isinstance(k, dict) and k.get("id") == api_key_id:
                k["last_used_at"] = now_iso
                k["updated_at"] = now_iso
                break

        _save("rate_limit_counters.json", counters)
        _save("api_keys.json", api_keys_rows)

    # ---- validate inputs ----
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key is required and must be a non-empty string", field="api_key")
    if owner_type is not None and (not isinstance(owner_type, str) or owner_type not in ("user", "service")):
        return _err("VALIDATION_ERROR", "owner_type must be one of: user, service", field="owner_type")
    if owner_id is not None and (not isinstance(owner_id, str) or not owner_id.strip()):
        return _err("VALIDATION_ERROR", "owner_id must be a non-empty string", field="owner_id")
    if status is not None and (not isinstance(status, str) or status not in ("active", "suspended", "revoked")):
        return _err("VALIDATION_ERROR", "status must be one of: active, suspended, revoked", field="status")
    if key_prefix is not None and (not isinstance(key_prefix, str) or not key_prefix.strip()):
        return _err("VALIDATION_ERROR", "key_prefix must be a non-empty string", field="key_prefix")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200", field="limit")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string", field="cursor")
    if sort is None:
        sort = "created_at"
    if not isinstance(sort, str) or sort not in ("created_at", "last_used_at", "updated_at"):
        return _err("VALIDATION_ERROR", "sort must be one of: created_at, last_used_at, updated_at", field="sort")
    if order is None:
        order = "desc"
    if not isinstance(order, str) or order not in ("asc", "desc"):
        return _err("VALIDATION_ERROR", "order must be one of: asc, desc", field="order")

    api_keys_rows = _load("api_keys.json")
    if not isinstance(api_keys_rows, list):
        api_keys_rows = []

    # ---- authenticate ----
    # Important: NEVER authenticate by comparing against key_hash (plaintext doesn't exist).
    # Accept either:
    #   - exact id match
    #   - exact key_prefix match (vendor allows identification by prefix)
    #   - if caller passed something that looks like a key id and exists, that's sufficient
    caller = None
    for r in api_keys_rows:
        if not isinstance(r, dict):
            continue
        if r.get("id") == api_key or r.get("key_prefix") == api_key:
            caller = r
            break
    if caller is None:
        # As a last resort: some clients pass full secret; we can match by prefix if stored.
        # Try to match any stored prefix that is a prefix of provided api_key.
        for r in api_keys_rows:
            if not isinstance(r, dict):
                continue
            pref = r.get("key_prefix")
            if isinstance(pref, str) and pref and api_key.startswith(pref):
                caller = r
                break
    if caller is None:
        return _err("UNAUTHORIZED", "Invalid api_key")

    # rate limiting for management calls too (per schema says includes failed/authenticated requests)
    # enforce using minute counter projected count (caller must exist)
    try:
        rl = int(caller.get("rate_limit_per_minute") or 0)
    except Exception:
        rl = 0
    if rl > 0:
        counters = _load("rate_limit_counters.json")
        if not isinstance(counters, list):
            counters = []
        minute_start = now.replace(second=0, microsecond=0)
        minute_iso = minute_start.isoformat() + "Z"
        existing = None
        for c in counters:
            if isinstance(c, dict) and c.get("api_key_id") == caller.get("id") and c.get("window_type") == "minute" and c.get("window_start") == minute_iso:
                existing = c
                break
        current = int((existing or {}).get("request_count") or 0)
        if current + 1 > rl:
            _record_request(caller.get("id"), 429, "rejected")
            return _err("RATE_LIMIT", "Rate limit exceeded for this API key (per-minute).")

    # ---- authorize / visibility rules ----
    # No explicit permissions model in schema; implement least-surprising:
    # caller can list keys owned by the same owner_type/owner_id. Also allow listing self key always.
    caller_owner_type = caller.get("owner_type")
    caller_owner_id = caller.get("owner_id")
    if caller_owner_type not in ("user", "service", "workspace") or not isinstance(caller_owner_id, str):
        # malformed caller row; treat as unauthorized
        _record_request(caller.get("id"), 401, "rejected")
        return _err("UNAUTHORIZED", "Caller credential is malformed.")

    visible = []
    for r in api_keys_rows:
        if not isinstance(r, dict):
            continue
        if r.get("id") == caller.get("id"):
            visible.append(r)
            continue
        if r.get("owner_type") == caller_owner_type and r.get("owner_id") == caller_owner_id:
            visible.append(r)

    # Apply optional filters
    def _match(r):
        if owner_type is not None and r.get("owner_type") != owner_type:
            return False
        if owner_id is not None and r.get("owner_id") != owner_id:
            return False
        if status is not None and r.get("status") != status:
            return False
        if key_prefix is not None and r.get("key_prefix") != key_prefix:
            return False
        return True

    filtered = [r for r in visible if _match(r)]

    # Sort
    reverse = (order == "desc")
    if sort in ("created_at", "updated_at", "last_used_at"):
        filtered.sort(key=lambda r: (_dt_key(r.get(sort)), str(r.get("id") or "")), reverse=reverse)
    else:
        filtered.sort(key=lambda r: str(r.get("id") or ""), reverse=reverse)

    # Cursor pagination: cursor is the last seen id from previous page in the current sort ordering.
    start_index = 0
    if cursor:
        idx = None
        for i, r in enumerate(filtered):
            if r.get("id") == cursor:
                idx = i
                break
        if idx is not None:
            start_index = idx + 1

    page = filtered[start_index:start_index + limit]
    has_more = start_index + limit < len(filtered)
    next_cursor = page[-1].get("id") if (has_more and page) else None

    _record_request(caller.get("id"), 200, "ok")

    return {
        "data": [_redact_key_row(r) for r in page],
        "meta": {
            "total": len(filtered),
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "sort": sort,
            "order": order,
        },
    }

def create_api_key(api_key, label, owner_type, owner_id, quota_requests_per_day=None, rate_limit_per_minute=None, allow_empty_query=None, **_extra):
    import json, os, datetime, secrets, hashlib, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0337000" if __import__("os").path.isdir("./environment_mix/0337000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _iso(dt):
        return dt.replace(microsecond=0).isoformat() + "Z"

    def _parse_iso(s):
        # Accept stored "....Z" and naive isoformat
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                return datetime.datetime.fromisoformat(s2)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _new_id(prefix):
        # Match existing id style: serper_key_01J...
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return prefix + "".join(secrets.choice(alphabet) for _ in range(26))

    def _is_nonempty_str(x, mn=1, mx=None):
        if not isinstance(x, str):
            return False
        if len(x) < mn:
            return False
        if mx is not None and len(x) > mx:
            return False
        return True

    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = _iso(now)

    # ---- validate inputs ----
    if not _is_nonempty_str(api_key, 1, None):
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string.")
    if not _is_nonempty_str(label, 1, 200):
        return _err("VALIDATION_ERROR", "label must be a non-empty string up to 200 characters.")
    if owner_type not in ("user", "service"):
        return _err("VALIDATION_ERROR", "owner_type must be one of: user, service.")
    if not _is_nonempty_str(owner_id, 1, None):
        return _err("VALIDATION_ERROR", "owner_id must be a non-empty string.")

    if quota_requests_per_day is None:
        quota_requests_per_day = 0
    if rate_limit_per_minute is None:
        rate_limit_per_minute = 0
    if allow_empty_query is None:
        allow_empty_query = False

    if not isinstance(quota_requests_per_day, int) or quota_requests_per_day < 0:
        return _err("VALIDATION_ERROR", "quota_requests_per_day must be an integer >= 0.")
    if not isinstance(rate_limit_per_minute, int) or rate_limit_per_minute < 0:
        return _err("VALIDATION_ERROR", "rate_limit_per_minute must be an integer >= 0.")
    if not isinstance(allow_empty_query, bool):
        return _err("VALIDATION_ERROR", "allow_empty_query must be a boolean.")

    # ---- load data ----
    api_keys_rows = _load("api_keys.json")
    if not isinstance(api_keys_rows, list):
        api_keys_rows = []
    counters = _load("rate_limit_counters.json")
    if not isinstance(counters, list):
        counters = []

    # ---- authenticate management request ----
    # IMPORTANT: never compare against key_hash using plaintext, because plaintext does not exist.
    # Accept api_key parameter matching either stored id or stored key_prefix (client-visible).
    auth_row = None
    for r in api_keys_rows:
        if not isinstance(r, dict):
            continue
        if r.get("id") == api_key or r.get("key_prefix") == api_key:
            auth_row = r
            break
    if auth_row is None:
        return _err("UNAUTHORIZED", "Invalid or unknown API key.")

    auth_key_id = auth_row.get("id")

    # ---- rate limit bookkeeping helper (observable dynamics) ----
    def _get_or_create_counter(api_key_id, window_type, window_start_iso):
        # window_start_iso should be ISO+Z
        for c in counters:
            if not isinstance(c, dict):
                continue
            if c.get("api_key_id") == api_key_id and c.get("window_type") == window_type and c.get("window_start") == window_start_iso:
                return c
        row = {
            "id": _new_id("serper_rlc_"),
            "api_key_id": api_key_id,
            "window_type": window_type,
            "window_start": window_start_iso,
            "request_count": 0,
            "success_count": 0,
            "rejected_count": 0,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        counters.append(row)
        return row

    def _minute_start(dt):
        return _iso(dt.replace(second=0, microsecond=0))

    # Always count authenticated management calls towards per-minute rate limiting (as described for requests).
    minute_start_iso = _minute_start(now)
    minute_counter = _get_or_create_counter(auth_key_id, "minute", minute_start_iso)

    # Enforce rate limit on management call if configured.
    # If auth key is not active, still record as rejected (business rule mentions google_search, but service behavior
    # should not allow suspended/revoked keys to manage other keys).
    def _persist_usage(outcome):
        # outcome: "rejected" or "succeeded"
        minute_counter["request_count"] = int(minute_counter.get("request_count") or 0) + 1
        if outcome == "rejected":
            minute_counter["rejected_count"] = int(minute_counter.get("rejected_count") or 0) + 1
        elif outcome == "succeeded":
            minute_counter["success_count"] = int(minute_counter.get("success_count") or 0) + 1
        minute_counter["updated_at"] = now_iso
        # last_used_at on auth key
        for r in api_keys_rows:
            if isinstance(r, dict) and r.get("id") == auth_key_id:
                r["last_used_at"] = now_iso
                r["updated_at"] = now_iso
                break
        _save("rate_limit_counters.json", counters)
        _save("api_keys.json", api_keys_rows)

    # Reject if key is not active (treat as unauthorized for auth failures)
    if auth_row.get("status") != "active":
        _persist_usage("rejected")
        return _err("UNAUTHORIZED", "API key is not active; request blocked.", api_key_id=auth_key_id)

    rl = auth_row.get("rate_limit_per_minute")
    if isinstance(rl, int) and rl > 0:
        projected = int(minute_counter.get("request_count") or 0) + 1
        if projected > rl:
            _persist_usage("rejected")
            return _err("RATE_LIMIT", "Rate limit exceeded for this API key (per-minute).", api_key_id=auth_key_id, limit_per_minute=rl)

    # ---- authorization (scope rules) ----
    # Realistic simplified rule: any active key may create keys for user/service scopes in this simplified backend,
    # because no other permission model is present in the datastore.
    # Therefore: no FORBIDDEN/UNAUTHORIZED for "owner scope" beyond schema validation.

    # ---- create secret + hash/prefix ----
    raw_secret = "serper_live_" + secrets.token_urlsafe(32)
    key_prefix = raw_secret[:10]

    key_hash = hashlib.sha256(raw_secret.encode("utf-8")).hexdigest()

    # ---- enforce uniqueness constraints ----
    for r in api_keys_rows:
        if not isinstance(r, dict):
            continue
        if r.get("key_hash") == key_hash:
            # Extremely unlikely; regenerate once
            raw_secret = "serper_live_" + secrets.token_urlsafe(32)
            key_prefix = raw_secret[:10]
            key_hash = hashlib.sha256(raw_secret.encode("utf-8")).hexdigest()
            break

    for r in api_keys_rows:
        if not isinstance(r, dict):
            continue
        if r.get("key_hash") == key_hash:
            _persist_usage("rejected")
            return _err("CONFLICT", "Generated key hash collided; please retry.")
        if r.get("key_prefix") == key_prefix and r.get("owner_id") == owner_id:
            _persist_usage("rejected")
            return _err("CONFLICT", "A key with this prefix already exists for the specified owner_id; please retry.")

    new_id = _new_id("serper_key_")
    existing_ids = {r.get("id") for r in api_keys_rows if isinstance(r, dict)}
    tries = 0
    while new_id in existing_ids and tries < 5:
        new_id = _new_id("serper_key_")
        tries += 1
    if new_id in existing_ids:
        _persist_usage("rejected")
        return _err("CONFLICT", "Could not allocate a unique key id; please retry.")

    new_row = {
        "id": new_id,
        "key_hash": key_hash,
        "key_prefix": key_prefix,
        "label": label,
        "owner_type": owner_type,
        "owner_id": owner_id,
        "status": "active",
        "quota_requests_per_day": int(quota_requests_per_day),
        "rate_limit_per_minute": int(rate_limit_per_minute),
        "allow_empty_query": bool(allow_empty_query),
        "last_used_at": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }

    api_keys_rows.append(new_row)
    _save("api_keys.json", api_keys_rows)

    # record successful management call usage
    _persist_usage("succeeded")

    # Return raw secret only at creation time, plus stored metadata
    return {
        "api_key": {
            "id": new_row["id"],
            "key_prefix": new_row["key_prefix"],
            "label": new_row["label"],
            "owner_type": new_row["owner_type"],
            "owner_id": new_row["owner_id"],
            "status": new_row["status"],
            "quota_requests_per_day": new_row["quota_requests_per_day"],
            "rate_limit_per_minute": new_row["rate_limit_per_minute"],
            "allow_empty_query": new_row["allow_empty_query"],
            "last_used_at": new_row["last_used_at"],
            "created_at": new_row["created_at"],
            "updated_at": new_row["updated_at"],
        },
        "api_key_secret": raw_secret,
        "meta": {
            "management_api_key_id": auth_key_id,
            "created_at": now_iso,
        },
    }

def update_api_key(api_key, id, label=None, quota_requests_per_day=None, rate_limit_per_minute=None, allow_empty_query=None, **_extra):
    import json, os, datetime, time, uuid, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0337000" if __import__("os").path.isdir("./environment_mix/0337000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Validate required
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key is required and must be a non-empty string")
    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "id is required and must be a non-empty string")

    # Validate optional fields
    if label is not None:
        if not isinstance(label, str):
            return _err("VALIDATION_ERROR", "label must be a string")
        if len(label) < 1 or len(label) > 200:
            return _err("VALIDATION_ERROR", "label length must be between 1 and 200")
    if quota_requests_per_day is not None:
        if not isinstance(quota_requests_per_day, int):
            return _err("VALIDATION_ERROR", "quota_requests_per_day must be an integer")
        if quota_requests_per_day < 0:
            return _err("VALIDATION_ERROR", "quota_requests_per_day must be >= 0")
    if rate_limit_per_minute is not None:
        if not isinstance(rate_limit_per_minute, int):
            return _err("VALIDATION_ERROR", "rate_limit_per_minute must be an integer")
        if rate_limit_per_minute < 0:
            return _err("VALIDATION_ERROR", "rate_limit_per_minute must be >= 0")
    if allow_empty_query is not None and not isinstance(allow_empty_query, bool):
        return _err("VALIDATION_ERROR", "allow_empty_query must be a boolean")

    api_keys = _load("api_keys.json")
    counters = _load("rate_limit_counters.json")

    # Authenticate management key: match by id OR key_prefix (plaintext secret is not available)
    authed = None
    for k in api_keys:
        if k.get("id") == api_key or k.get("key_prefix") == api_key:
            authed = k
            break

    if authed is None:
        # log rejected attempt (no api_key_id available)
        reqlog = _load("search_requests.json")
        rid = "sr_" + uuid.uuid4().hex
        reqlog.append({
            "id": rid,
            "api_key_id": "unknown",
            "status": "rejected",
            "tool_name": "google_search",
            "input_params": {},
            "query_text": None,
            "locale": None,
            "country": None,
            "safe_search": None,
            "upstream_provider": "serper",
            "upstream_request_id": None,
            "http_status": 401,
            "error_code": "UNAUTHORIZED",
            "error_message": "Invalid API key",
            "started_at": now,
            "finished_at": now,
            "duration_ms": int((time.time() - t0) * 1000),
            "created_at": now,
            "updated_at": now
        })
        _save("search_requests.json", reqlog)
        return _err("UNAUTHORIZED", "Invalid api_key")

    # Authorize: must be able to modify the target key; simplified rule: same owner_type+owner_id OR same key id
    target = None
    for k in api_keys:
        if k.get("id") == id:
            target = k
            break
    if target is None:
        return _err("NOT_FOUND", "API key not found")

    if not (authed.get("id") == target.get("id") or (authed.get("owner_type") == target.get("owner_type") and authed.get("owner_id") == target.get("owner_id"))):
        return _err("UNAUTHORIZED", "Not permitted to modify this API key")

    # Apply updates (must have at least one mutable field)
    mutable = False
    if label is not None:
        target["label"] = label
        mutable = True
    if quota_requests_per_day is not None:
        target["quota_requests_per_day"] = quota_requests_per_day
        mutable = True
    if rate_limit_per_minute is not None:
        target["rate_limit_per_minute"] = rate_limit_per_minute
        mutable = True
    if allow_empty_query is not None:
        target["allow_empty_query"] = allow_empty_query
        mutable = True

    if not mutable:
        return _err("VALIDATION_ERROR", "At least one of label, quota_requests_per_day, rate_limit_per_minute, allow_empty_query must be provided")

    # Constraints sanity
    if not isinstance(target.get("quota_requests_per_day"), int) or target["quota_requests_per_day"] < 0:
        return _err("VALIDATION_ERROR", "quota_requests_per_day must be >= 0")
    if not isinstance(target.get("rate_limit_per_minute"), int) or target["rate_limit_per_minute"] < 0:
        return _err("VALIDATION_ERROR", "rate_limit_per_minute must be >= 0")
    if not isinstance(target.get("allow_empty_query"), bool):
        return _err("VALIDATION_ERROR", "allow_empty_query must be a boolean")

    target["updated_at"] = now

    # Persist
    _save("api_keys.json", api_keys)

    # Record observable dynamics in counters: count this authenticated management request in minute window
    # (includes failed/authenticated requests per rules; this is authenticated and succeeded as management op)
    def _parse_iso_z(s):
        if s is None:
            return None
        if isinstance(s, str):
            try:
                if s.endswith("Z"):
                    s2 = s[:-1]
                    return datetime.datetime.fromisoformat(s2)
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None
        return None

    dt = _parse_iso_z(now)
    if dt is None:
        dt = datetime.datetime.utcnow().replace(microsecond=0)
    minute_start = dt.replace(second=0, microsecond=0).isoformat() + "Z"

    # Find/create minute counter row
    found = None
    for c in counters:
        if c.get("api_key_id") == authed["id"] and c.get("window_type") == "minute" and c.get("window_start") == minute_start:
            found = c
            break
    if found is None:
        found = {
            "id": "rlc_" + uuid.uuid4().hex,
            "api_key_id": authed["id"],
            "window_type": "minute",
            "window_start": minute_start,
            "request_count": 0,
            "success_count": 0,
            "rejected_count": 0,
            "created_at": now,
            "updated_at": now
        }
        counters.append(found)
    found["request_count"] = int(found.get("request_count") or 0) + 1
    found["updated_at"] = now
    _save("rate_limit_counters.json", counters)

    # Update last_used_at for the authed key
    for k in api_keys:
        if k.get("id") == authed["id"]:
            k["last_used_at"] = now
            k["updated_at"] = now
            break
    _save("api_keys.json", api_keys)

    # Return sanitized key record (no secret material, but key_hash and key_prefix are stored fields; keep key_hash but it's hashed)
    out = {f: target.get(f) for f in [
        "id", "key_prefix", "label", "owner_type", "owner_id", "status",
        "quota_requests_per_day", "rate_limit_per_minute", "allow_empty_query",
        "last_used_at", "created_at", "updated_at"
    ]}
    return {"api_key": out}

def set_api_key_status(api_key, id, status, reason=None, **_extra):
    import json, os, datetime, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0337000" if __import__("os").path.isdir("./environment_mix/0337000") else "/app/database")
    def _load(n):
