        row = None
        for c in counters:
            if isinstance(c, dict) and c.get("api_key_id") == api_key_id and c.get("window_type") == "minute" and c.get("window_start") == minute_start:
                row = c
                break
        if row is None:
            row = {
                "id": "serper_rlc_" + secrets.token_hex(12),
                "api_key_id": api_key_id,
                "window_type": "minute",
                "window_start": minute_start,
                "request_count": 0,
                "success_count": 0,
                "rejected_count": 0,
                "created_at": now_iso,
                "updated_at": now_iso,
            }
            counters.append(row)
        row["request_count"] = int(row.get("request_count") or 0) + 1
        if outcome == "rejected":
            row["rejected_count"] = int(row.get("rejected_count") or 0) + 1
        row["updated_at"] = now_iso

        if isinstance(api_keys_rows, list):
            for k in api_keys_rows:
                if isinstance(k, dict) and k.get("id") == api_key_id:
                    k["last_used_at"] = now_iso
                    k["updated_at"] = now_iso
                    break

        _save("rate_limit_counters.json", counters)
        _save("api_keys.json", api_keys_rows if isinstance(api_keys_rows, list) else [])

    # ---- validate ----
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key is required and must be a non-empty string", field="api_key")
    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "id is required and must be a non-empty string", field="id")
    if not isinstance(status, str) or status not in ("active", "suspended", "revoked"):
        return _err("VALIDATION_ERROR", "status must be one of: active, suspended, revoked", field="status")
    if reason is not None:
        if not isinstance(reason, str):
            return _err("VALIDATION_ERROR", "reason must be a string", field="reason")
        if len(reason) > 500:
            return _err("VALIDATION_ERROR", "reason max length is 500", field="reason")

    api_keys_rows = _load("api_keys.json")
    if not isinstance(api_keys_rows, list):
        api_keys_rows = []

    # ---- authenticate ----
    authed = None
    for k in api_keys_rows:
        if not isinstance(k, dict):
            continue
        if k.get("id") == api_key or k.get("key_prefix") == api_key:
            authed = k
            break
    if authed is None:
        for k in api_keys_rows:
            if not isinstance(k, dict):
                continue
            pref = k.get("key_prefix")
            if isinstance(pref, str) and pref and api_key.startswith(pref):
                authed = k
                break
    if authed is None:
        return _err("UNAUTHORIZED", "Invalid api_key")

    # ---- rate limit check ----
    try:
        rl = int(authed.get("rate_limit_per_minute") or 0)
    except Exception:
        rl = 0
    if rl > 0:
        counters = _load("rate_limit_counters.json")
        if not isinstance(counters, list):
            counters = []
        minute_start = now.replace(second=0, microsecond=0).isoformat() + "Z"
        existing = None
        for c in counters:
            if isinstance(c, dict) and c.get("api_key_id") == authed.get("id") and c.get("window_type") == "minute" and c.get("window_start") == minute_start:
                existing = c
                break
        current = int((existing or {}).get("request_count") or 0)
        if current + 1 > rl:
            _record_request(authed.get("id"), "rejected")
            return _err("RATE_LIMIT", "Rate limit exceeded for this API key (per-minute).")

    # ---- find target ----
    target_index = None
    for i, k in enumerate(api_keys_rows):
        if isinstance(k, dict) and k.get("id") == id:
            target_index = i
            break
    if target_index is None:
        _record_request(authed.get("id"), "rejected")
        return _err("NOT_FOUND", "API key not found", field="id")

    target = api_keys_rows[target_index]

    # ---- authorize ----
    # Allow:
    #  - service owners manage any key
    #  - same owner scope manages within scope
    if authed.get("owner_type") == "service":
        allowed = True
    else:
        allowed = (authed.get("owner_type") == target.get("owner_type") and authed.get("owner_id") == target.get("owner_id")) or (authed.get("id") == target.get("id"))
    if not allowed:
        _record_request(authed.get("id"), "rejected")
        return _err("UNAUTHORIZED", "Not permitted to manage this API key")

    # ---- lifecycle transition ----
    transitions = {
        "active": ["suspended", "revoked"],
        "suspended": ["active", "revoked"],
        "revoked": [],
    }
    cur = target.get("status")
    if cur not in transitions:
        _record_request(authed.get("id"), "rejected")
        return _err("VALIDATION_ERROR", "Current key status is invalid", field="status")

    if status == cur:
        # idempotent: still must be observable (last_used/counter updated above/below)
        _record_request(authed.get("id"), "ok")
        return {
            "data": {
                "id": target.get("id"),
                "status": target.get("status"),
                "updated_at": target.get("updated_at"),
                "reason": reason,
            }
        }

    if status not in transitions[cur]:
        _record_request(authed.get("id"), "rejected")
        return _err("INVALID_TRANSITION", f"Illegal status transition: {cur} -> {status}", from_status=cur, to_status=status)

    # ---- apply mutation + persist ----
    target["status"] = status
    target["updated_at"] = now_iso
    # store reason in label suffix is not allowed; no field exists. We only return it.
    api_keys_rows[target_index] = target
    _save("api_keys.json", api_keys_rows)

    _record_request(authed.get("id"), "ok")

    return {
        "data": {
            "id": target.get("id"),
            "status": target.get("status"),
            "updated_at": target.get("updated_at"),
            "reason": reason,
        }
    }

def list_search_requests(api_key, status=None, tool_name=None, from_created_at=None, to_created_at=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, time, uuid, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0337000" if __import__("os").path.isdir("./environment_mix/0337000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key is required and must be a non-empty string")
    if status is not None and status not in ("queued", "running", "succeeded", "failed", "rejected"):
        return _err("VALIDATION_ERROR", "status must be one of queued, running, succeeded, failed, rejected")
    if tool_name is not None and tool_name != "google_search":
        return _err("VALIDATION_ERROR", "tool_name must be google_search when provided")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")
    if sort is None:
        sort = "created_at"
    if sort not in ("created_at", "started_at", "finished_at"):
        return _err("VALIDATION_ERROR", "sort must be one of created_at, started_at, finished_at")
    if order is None:
        order = "desc"
    if order not in ("asc", "desc"):
        return _err("VALIDATION_ERROR", "order must be asc or desc")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string")

    def _parse_rfc3339(s, field_name):
        if s is None:
            return None, None
        if not isinstance(s, str):
            return None, _err("VALIDATION_ERROR", f"{field_name} must be a string (RFC 3339)")
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]), None
            return datetime.datetime.fromisoformat(s), None
        except Exception:
            return None, _err("VALIDATION_ERROR", f"{field_name} must be a valid RFC 3339 timestamp")

    from_dt, e = _parse_rfc3339(from_created_at, "from_created_at")
    if e: return e
    to_dt, e = _parse_rfc3339(to_created_at, "to_created_at")
    if e: return e

    api_keys = _load("api_keys.json")
    reqs = _load("search_requests.json")
    counters = _load("rate_limit_counters.json")

    # Authenticate
    authed = None
    for k in api_keys:
        if k.get("id") == api_key or k.get("key_prefix") == api_key:
            authed = k
            break
    if authed is None:
        return _err("UNAUTHORIZED", "Invalid api_key")

    # Authorization scope: same owner can view, simplified to owner match only
    owner_type = authed.get("owner_type")
    owner_id = authed.get("owner_id")

    # Cursor decode: base64url json {"offset": int}
    offset = 0
    if cursor:
        try:
            pad = "=" * ((4 - len(cursor) % 4) % 4)
            raw = base64.urlsafe_b64decode((cursor + pad).encode("utf-8")).decode("utf-8")
            obj = json.loads(raw)
            if not isinstance(obj, dict) or "offset" not in obj or not isinstance(obj["offset"], int) or obj["offset"] < 0:
                return _err("VALIDATION_ERROR", "Invalid cursor")
            offset = obj["offset"]
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid cursor")

    # Build set of key ids within same owner for scoping
    scoped_key_ids = set()
    for k in api_keys:
        if k.get("owner_type") == owner_type and k.get("owner_id") == owner_id:
            scoped_key_ids.add(k.get("id"))

    if authed.get("id") not in scoped_key_ids:
        return _err("UNAUTHORIZED", "Not permitted to view these records")

    def _to_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    filtered = []
    for r in reqs:
        if r.get("api_key_id") not in scoped_key_ids:
            continue
        if status is not None and r.get("status") != status:
            continue
        if tool_name is not None and r.get("tool_name") != tool_name:
            continue
        cdt = _to_dt(r.get("created_at"))
        if from_dt is not None and (cdt is None or cdt < from_dt):
            continue
        if to_dt is not None and (cdt is None or cdt > to_dt):
            continue
        filtered.append(r)

    # Sort
    def _sort_key(r):
        v = r.get(sort)
        d = _to_dt(v)
        # None sorts last in asc, first in desc; emulate by using min/max sentinel
        if d is None:
            return datetime.datetime.min if order == "desc" else datetime.datetime.max
        return d

    reverse = (order == "desc")
    filtered.sort(key=_sort_key, reverse=reverse)

    total = len(filtered)
    page = filtered[offset:offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        payload = json.dumps({"offset": next_offset}, separators=(",", ":")).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

    # Record observable dynamics: authenticated read increments minute counter request_count
    dt = datetime.datetime.utcnow().replace(microsecond=0)
    minute_start = dt.replace(second=0, microsecond=0).isoformat() + "Z"
    found = None
    for c in counters:
        if c.get("api_key_id") == authed["id"] and c.get("window_type") == "minute" and c.get("window_start") == minute_start:
            found = c
            break
    if found is None:
        found = {
            "id": "rlc_" + uuid.uuid4().hex,
            "api_key_id": authed["id"],
            "window_type": "minute",
            "window_start": minute_start,
            "request_count": 0,
            "success_count": 0,
            "rejected_count": 0,
            "created_at": now,
            "updated_at": now
        }
        counters.append(found)
    found["request_count"] = int(found.get("request_count") or 0) + 1
    found["updated_at"] = now
    _save("rate_limit_counters.json", counters)

    # Touch last_used_at for authed key
    for k in api_keys:
        if k.get("id") == authed["id"]:
            k["last_used_at"] = now
            k["updated_at"] = now
            break
    _save("api_keys.json", api_keys)

    # Return sanitized request rows (no raw payload here)
    def _pick(r):
        return {
            "id": r.get("id"),
            "api_key_id": r.get("api_key_id"),
            "status": r.get("status"),
            "tool_name": r.get("tool_name"),
            "input_params": r.get("input_params"),
            "query_text": r.get("query_text"),
            "locale": r.get("locale"),
            "country": r.get("country"),
            "safe_search": r.get("safe_search"),
            "upstream_provider": r.get("upstream_provider"),
            "upstream_request_id": r.get("upstream_request_id"),
            "http_status": r.get("http_status"),
            "error_code": r.get("error_code"),
            "error_message": r.get("error_message"),
            "started_at": r.get("started_at"),
            "finished_at": r.get("finished_at"),
            "duration_ms": r.get("duration_ms"),
            "created_at": r.get("created_at"),
            "updated_at": r.get("updated_at"),
        }

    return {
        "data": [_pick(r) for r in page],
        "meta": {
            "total": total,
            "limit": limit,
            "offset": offset,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "sort": sort,
            "order": order,
            "duration_ms": int((time.time() - t0) * 1000)
        }
    }
